class HungarianAlgorithm {
public:
    static const int MAX_SIZE = 2000;
    int matchCount, matchPos[MAX_SIZE], matchRev[MAX_SIZE];
    int maxMatching(int n, vector<int> adj[]) {
        matchCount = 0;
        memset(matchPos, -1, sizeof(matchPos));
        memset(matchRev, -1, sizeof(matchRev));
        for (int i = 0; i < n; i++) {
            memset(visited, 0, sizeof(visited));
            if (tryMatch(i, adj)) matchCount++;
        }
        return matchCount;
    }
private:
    int visited[MAX_SIZE];
    bool tryMatch(int u, vector<int> adj[]) {
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = 1;
                if (matchRev[v] < 0 || tryMatch(matchRev[v], adj)) {
                    matchPos[u] = v;
                    matchRev[v] = u;
                    return true;
                }
            }
        }
        return false;
    }
};

