import java.util.*;
import java.io.*;

public class Main {
    static class HungarianAlgorithm {
        public static final int MAX_SIZE = 2000;
        int matchCount, matchPos[], matchRev[];
        public HungarianAlgorithm() {
            matchPos = new int[MAX_SIZE];
            matchRev = new int[MAX_SIZE];
        }
        public int maxMatching(int n, List<Integer>[] adj) {
            matchCount = 0;
            Arrays.fill(matchPos, -1);
            Arrays.fill(matchRev, -1);
            boolean[] visited = new boolean[MAX_SIZE];
            for (int i = 0; i < n; i++) {
                Arrays.fill(visited, false);
                if (tryMatch(i, adj, visited)) matchCount++;
            }
            return matchCount;
        }
        private boolean tryMatch(int u, List<Integer>[] adj, boolean[] visited) {
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    if (matchRev[v] < 0 || tryMatch(matchRev[v], adj, visited)) {
                        matchPos[u] = v;
                        matchRev[v] = u;
                        return true;
                    }
                }
            }
            return false;
        }
    }

    static final int INF = 1000000000;
    static final int[] dirR = {0, -1, 0, 1};
    static final int[] dirC = {1, 0, -1, 0};
    static int[][] gridA = new int[12][12];
    static int[][] gridB = new int[12][12];
    static int[][] distF = new int[12][12];
    static int n, t, sizeN, timeT;
    static List<Integer>[] edges = new ArrayList[2000];
    static List<Integer>[][] cellGroups = new ArrayList[12][12];

    static {
        for (int i = 0; i < 2000; i++) {
            edges[i] = new ArrayList<>();
        }
        for (int i = 0; i < 12; i++) {
            for (int j = 0; j < 12; j++) {
                cellGroups[i][j] = new ArrayList<>();
            }
        }
    }

    static void floodFill(int startR, int startC) {
        for (int i = 0; i < 12; i++) {
            Arrays.fill(distF[i], -1);
        }
        Queue<Integer> qRow = new LinkedList<>();
        Queue<Integer> qCol = new LinkedList<>();
        qRow.offer(startR);
        qCol.offer(startC);
        distF[startR][startC] = 0;
        while (!qRow.isEmpty()) {
            int r = qRow.poll();
            int c_ = qCol.poll();
            for (int i = 0; i < 4; i++) {
                int nr = r + dirR[i];
                int nc = c_ + dirC[i];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && gridA[nr][nc] >= 0 && distF[nr][nc] < 0) {
                    distF[nr][nc] = distF[r][c_] + 1;
                    qRow.offer(nr);
                    qCol.offer(nc);
                }
            }
        }
    }

    static void assignMarks(int r, int c, int count) {
        int[][] visitedV = new int[12][12];
        for (int[] row : visitedV) {
            Arrays.fill(row, -1);
        }
        Queue<Integer> qRow = new LinkedList<>();
        Queue<Integer> qCol = new LinkedList<>();
        qRow.offer(r);
        qCol.offer(c);
        visitedV[r][c] = 0;
        while (!qRow.isEmpty()) {
            int rr = qRow.poll();
            int cc = qCol.poll();
            if (visitedV[rr][cc] > Math.min(timeT, distF[rr][cc])) continue;
            for (int groupIdx : cellGroups[rr][cc]) {
                for (int i = 0; i < count; i++) {
                    edges[sizeN + i].add(groupIdx);
                }
            }
            if (visitedV[rr][cc] == Math.min(timeT, distF[rr][cc])) continue;
            for (int i = 0; i < 4; i++) {
                int nr = rr + dirR[i];
                int nc = cc + dirC[i];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && gridA[nr][nc] >= 0 && visitedV[nr][nc] < 0) {
                    visitedV[nr][nc] = visitedV[rr][cc] + 1;
                    qRow.offer(nr);
                    qCol.offer(nc);
                }
            }
        }
        sizeN += count;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        for (int i = 0; i < 12; i++) {
            Arrays.fill(gridA[i], -1);
            Arrays.fill(gridB[i], -1);
        }
        int startR = -1, startC = -1;
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = line.charAt(j);
                if (ch >= '0' && ch <= '9') {
                    gridA[i][j] = ch - '0';
                }
                if (ch == 'Z') {
                    startR = i;
                    startC = j;
                }
            }
        }
        floodFill(startR, startC);
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = line.charAt(j);
                if (ch >= '0' && ch <= '9') {
                    gridB[i][j] = ch - '0';
                }
                for (int k = 0; k < gridB[i][j]; k++) {
                    cellGroups[i][j].add(totalEdges++);
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (distF[i][j] < 0) distF[i][j] = INF;
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gridA[i][j] > 0) assignMarks(i, j, gridA[i][j]);
            }
        }
        HungarianAlgorithm matcher = new HungarianAlgorithm();
        System.out.println(matcher.maxMatching(totalEdges, edges));
    }
}
